import json

with open('/root/afford_invar/data/paraphrases.json') as f:
    data = json.load(f)

print(f'Total keys: {len(data)}')
print(f'Type of values: {type(list(data.values())[0])}')

# Check for empty or missing paraphrases
empty = []
has_para = []
for k, v in sorted(data.items()):
    if isinstance(v, list):
        if len(v) == 0:
            empty.append(k)
        else:
            has_para.append(k)
    elif isinstance(v, dict):
        paras = v.get('paraphrases', v.get('paraphrase', []))
        if not paras:
            empty.append(k)
        else:
            has_para.append(k)
    elif isinstance(v, str):
        if not v.strip():
            empty.append(k)
        else:
            has_para.append(k)
    else:
        print(f'  Unexpected type for {k}: {type(v)}')

print(f'\nWith paraphrases: {len(has_para)}')
print(f'Empty/missing: {len(empty)}')
if empty:
    print('Empty tasks:')
    for t in empty:
        print(f'  {t}')

# Show a sample
sample_key = list(data.keys())[0]
sample_val = data[sample_key]
print(f'\nSample - {sample_key}:')
if isinstance(sample_val, (list, dict)):
    print(json.dumps(sample_val, indent=2)[:500])
else:
    print(str(sample_val)[:500])
"
